def _term(t):
    if t is None:
        return None
    return str(t).replace(" ", "")

def _terms(lst):
    if lst is None:
        return None
    return [_term(t) for t in list(lst)]

def _ints(v):
    if v is None:
        return None
    try:
        return [int(x) for x in list(v)]
    except TypeError:
        pass
    for attr in ("getArray", "get_array", "toArray", "to_array"):
        fn = getattr(v, attr, None)
