    return [_ints(x) for x in list(lst)]

def _sets(lst):
    if lst is None:
        return None
    return [sorted(int(x) for x in list(s)) for s in list(lst)]

def _cyclic_gens(vals):
    try:
        from jarray import array
        v = array(vals, 'i')
    except ImportError:
        v = vals
    return _ias(Malcev.makeCyclicGens(v))

